from pathlib import Path
import argparse,hashlib,importlib.util,json,math,statistics,subprocess,sys,platform
sys.dont_write_bytecode=True
root=Path(__file__).resolve().parents[2];out=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('bench',root/'scripts/benchmark-runtime.py');bench=importlib.util.module_from_spec(spec);spec.loader.exec_module(bench)
bench.cpu_affinity(0)
bins={'baseline':root/'.work/vm-pc-windows-20261115/baseline/bin/sigma.exe','candidate':out/'windows/bin/sigma.exe'}
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(name):return json.loads((out/name).read_text(encoding='utf8'))
def write(name,value):(out/name).write_text(json.dumps(value,indent=2)+'\n')
def definition(case,n):return f'{n} CONSTANT BENCH-ITERATIONS {case["definition"]} '+'." BENCH-READY" CR KEY DROP BENCH-RUN ." BENCH-DONE " . CR KEY DROP BYE'
cal=read('cases.json');parser=argparse.ArgumentParser();parser.add_argument('stage',choices=['calibrate','aa','compare']);parser.add_argument('--series',type=int,choices=[1,2],default=1);parser.add_argument('--pass-number',type=int,default=0);args=parser.parse_args()
selected=cal['cases'] if args.pass_number==0 else {k:v for k,v in cal['cases'].items() if v.get('calibration_pass',0)==args.pass_number}
if args.stage=='calibrate' and args.pass_number>=2 and (out/'primary-checkpoint').exists():
 print('Checkpoint: assess primary kernels before further calibration',flush=True)
 raise SystemExit(75)
if args.stage=='calibrate':
 for name,case in selected.items():
  n=case['iterations'];samples=[]
  for attempt in range(4):
   cpu,checksum,wall,total=bench.sample(str(bins['baseline']),False,definition(case,n));samples.append({'iterations':n,'cpu_us':cpu,'wall_us':wall,'checksum':checksum})
   if case.get('checksum_per_iteration') is not None:assert checksum==n*case['checksum_per_iteration']
   if cpu>=1_000_000:break
   n=max(n+1,math.ceil(n*1_200_000/cpu));
   if case['group']=='normal':n=math.ceil(n/10_000_000)*10_000_000
  assert cpu>=1_000_000,(name,samples)
  case['iterations']=n;case['calibration_samples']=samples;write('cases.json',cal);print(name,n,cpu,flush=True)
else:
 report={'stage':args.stage,'series':args.series,'pass_number':args.pass_number,'pid':__import__('os').getpid(),'platform':platform.platform(),'cpu_affinity':bench.cpu_affinity(),'rounds':5 if args.stage=='aa' else 5,'timing':'GetProcessTimes kernel+user delta between READY/DONE; startup/compilation excluded, boundary IO included','engines':{k:{'path':str(p),'sha256':digest(p)} for k,p in bins.items()},'cases':{}}
 for name,case in selected.items():
  engines={'A1':bins['baseline'],'A2':bins['baseline']} if args.stage=='aa' else bins
  vals={k:[] for k in engines};walls={k:[] for k in engines};totals={k:[] for k in engines};expected=None;orders=[]
  for index in range(report['rounds']+1):
   order=list(engines) if (args.series-1+index)%2==0 else list(reversed(engines));orders.append(order)
   for label in order:
    cpu,checksum,wall,total=bench.sample(str(engines[label]),False,definition(case,case['iterations']))
    if expected is None:expected=checksum
    assert checksum==expected,(name,label,checksum,expected)
    if case.get('checksum_per_iteration') is not None:assert checksum==case['iterations']*case['checksum_per_iteration']
    if index:vals[label].append(cpu);walls[label].append(wall);totals[label].append(total)
  rows={k:{'samples_us':v,'median_us':statistics.median(v),'min_us':min(v),'max_us':max(v),'wall_samples_us':walls[k],'total_process_cpu_samples_us':totals[k]} for k,v in vals.items()}
  left,right=('A1','A2') if args.stage=='aa' else ('baseline','candidate');change=100*(rows[right]['median_us']/rows[left]['median_us']-1)
  report['cases'][name]={'group':case['group'],'iterations':case['iterations'],'definition':case['definition'],'orders':orders,'checksum':expected,'engines':rows,'change_percent':change}
  write(f'{args.stage}-{args.pass_number}-{args.series}.json',report);print(name,change,flush=True)

